export const c11Phy4HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS -->\n  <div style=\"background: rgba(0, 198, 255, 0.05); border: 1.5px solid #00c6ff; border-radius: 12px; padding: 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #00c6ff; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #00c6ff; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Essential Core Terms for Unit III: Laws of Motion</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>1. Force (F⃗):</b>\n        <span style=\"color: #FFFFFF;\">An external push or pull acting upon a body that changes or tends to change its state of rest or uniform motion.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>2. Inertia:</b>\n        <span style=\"color: #FFFFFF;\">The natural resistance of a body to any change in its state of rest or uniform motion (measured quantitatively by mass).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>3. Linear Momentum (p⃗):</b>\n        <span style=\"color: #FFFFFF;\">The quantity of motion possessed by a body, defined as product of mass and velocity: p⃗ = m v⃗ [kg m/s].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>4. Newton's Second Law:</b>\n        <span style=\"color: #FFFFFF;\">The rate of change of momentum is directly proportional to applied net force: F⃗ = dp⃗/dt = m a⃗.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>5. Impulse (J⃗):</b>\n        <span style=\"color: #FFFFFF;\">The product of a large force acting over a short time interval: J⃗ = F⃗ Δt = Δp⃗ (Impulse-Momentum Theorem).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>6. Conservation of Momentum:</b>\n        <span style=\"color: #FFFFFF;\">If net external force on a system is zero (F_ext = 0), the total momentum remains constant: p⃗_total = Const.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>7. Friction &amp; Laws of Friction:</b>\n        <span style=\"color: #FFFFFF;\">Tangential contact force opposing relative motion. Static friction f_s ≤ μ_s N, Kinetic friction f_k = μ_k N.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>8. Banking of Roads:</b>\n        <span style=\"color: #FFFFFF;\">Tilting the outer edge of a curved road above inner edge to provide necessary centripetal force without relying on friction alone.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1: INERTIA & NEWTON'S FIRST LAW -->\n  <h2 style=\"color: #00c6ff; border-bottom: 2px solid #00c6ff; padding-bottom: 6px; margin-top: 25px;\">1. Intuitive Concept of Force, Inertia &amp; Newton's First Law of Motion</h2>\n\n  <p>Dynamics investigates the physical interactions that alter the motion of bodies. <b>Newton's First Law of Motion</b> states that every body continues in its state of rest or uniform motion along a straight line unless acted upon by a non-zero net external force.</p>\n\n  <p><b>Inertia</b> is the intrinsic property of matter that resists changes in motion. It exists in three forms: Inertia of Rest (a stationary bus starting abruptly causes passengers to fall backward), Inertia of Motion (a moving bus stopping abruptly causes passengers to lurch forward), and Inertia of Direction (a turning car causes passengers to lean outward).</p>\n\n  <!-- SECTION 2 & 3: MOMENTUM, SECOND LAW & IMPULSE -->\n  <h2 style=\"color: #00c6ff; border-bottom: 2px solid #00c6ff; padding-bottom: 6px; margin-top: 30px;\">2. Momentum, Newton's Second Law &amp; Impulse-Momentum Theorem</h2>\n\n  <p><b>Newton's Second Law of Motion</b> defines force quantitatively. The time rate of change of linear momentum ($mathbf{p} = m mathbf{v}$) of a body is directly proportional to the applied net external force and takes place in the direction of the force:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(0, 198, 255, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>F⃗ = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">dp⃗</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">dt</span>\n  </span> = m <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">dv⃗</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">dt</span>\n  </span> = m a⃗ &nbsp;|&nbsp; Impulse J⃗ = ∫ F⃗ dt = Δp⃗</b></div>\n\n  <p>The <b>Impulse-Momentum Theorem</b> states that the net impulse imparted to a body by a force over a time interval $Delta t$ equals the net change in its linear momentum. Catching a cricket ball by pulling hands backward increases $Delta t$, thereby reducing the impact force $F = \frac{Delta p}{Delta t}$ and preventing hand injury.</p>\n\n  <!-- SECTION 4 & 5: THIRD LAW & MOMENTUM CONSERVATION -->\n  <h2 style=\"color: #00c6ff; border-bottom: 2px solid #00c6ff; padding-bottom: 6px; margin-top: 30px;\">3. Newton's Third Law of Motion &amp; Law of Conservation of Linear Momentum</h2>\n\n  <p><b>Newton's Third Law</b> asserts that to every action force, there is always an equal and opposite reaction force ($mathbf{F}_{AB} = -mathbf{F}_{BA}$). Action and reaction forces act simultaneously on two different bodies and never cancel each other out.</p>\n\n  <p>The <b>Law of Conservation of Linear Momentum</b> states that if the net external force acting on a system of interacting particles is zero ($mathbf{F}_{\text{ext}} = 0$), the total linear momentum of the system remains constant over time. Examples include gun recoil velocity ($v_{\text{recoil}} = -\frac{m}{M} v$) and rocket propulsion.</p>\n\n  <!-- SECTION 7 & 8: FRICTION & DYNAMICS OF CIRCULAR MOTION -->\n  <h2 style=\"color: #00c6ff; border-bottom: 2px solid #00c6ff; padding-bottom: 6px; margin-top: 30px;\">4. Static and Kinetic Friction, Dynamics of Circular Motion &amp; Banking of Roads</h2>\n\n  <p><b>Friction</b> is an electromagnetic contact force acting parallel to the surface interface opposing relative motion. Static friction ($f_s le mu_s N$) is self-adjusting up to a maximum limiting value ($f_{s,\text{max}} = mu_s N$). Once sliding begins, kinetic friction ($f_k = mu_k N$) opposes relative motion ($mu_k < mu_s$).</p>\n\n  <p>On curved roads of radius $r$, the maximum safe speed without skidding on a flat road is $v_{\text{max}} = sqrt{mu_s g r}$. By <b>banking the road</b> at angle $\theta$, the normal contact force component $N sin\theta$ provides centripetal acceleration, raising the optimum safe speed to:</p>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(0, 198, 255, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>f<sub>s</sub> ≤ μ<sub>s</sub> N &nbsp;|&nbsp; Banking Speed: v<sub>max</sub> = √[ g r <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">tanθ + μ<sub>s</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">1 - μ<sub>s</sub> tanθ</span>\n  </span> ]</b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #00c6ff; border-radius: 16px; padding: 18px; margin: 26px 0; box-shadow: 0 10px 30px rgba(0, 198, 255, 0.25);\">\n    <div style=\"color: #00c6ff; font-weight: bold; font-size: 17.5px; margin-bottom: 14px; text-align: center; letter-spacing: 0.5px;\">\n      📍 Banking of Circular Curved Roads & Optimum Speed Model\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 840 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <g transform=\"translate(15, 20)\">\n    <text x=\"390\" y=\"30\" text-anchor=\"middle\" fill=\"#00c6ff\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Banking of Circular Curved Roads &amp; Optimum Safe Speed</text>\n\n    <!-- Incline Road at Angle θ -->\n    <polygon points=\"100,340 680,340 680,180\" fill=\"rgba(0,198,255,0.1)\" stroke=\"#00c6ff\" stroke-width=\"2.5\"/>\n    <text x=\"220\" y=\"325\" fill=\"#00c6ff\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Banking Angle θ</text>\n\n    <!-- Vehicle Block -->\n    <rect x=\"360\" y=\"220\" width=\"100\" height=\"50\" rx=\"8\" fill=\"#FF512F\" transform=\"rotate(-15, 410, 245)\"/>\n    <text x=\"410\" y=\"250\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\" transform=\"rotate(-15, 410, 245)\">Car Mass m</text>\n\n    <!-- Force Vectors -->\n    <line x1=\"410\" y1=\"245\" x2=\"410\" y2=\"340\" stroke=\"#76FF03\" stroke-width=\"3\"/>\n    <text x=\"420\" y=\"320\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Weight mg ↓</text>\n\n    <line x1=\"410\" y1=\"245\" x2=\"350\" y2=\"120\" stroke=\"#FFD700\" stroke-width=\"3\"/>\n    <text x=\"320\" y=\"130\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Normal Contact N</text>\n\n    <text x=\"390\" y=\"420\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Optimum Speed v_max = √[ g r (tanθ + μ_s) / (1 - μ_s tanθ) ]</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Free body diagram of vehicle on banked road at angle θ, balancing Normal component N sinθ and friction f_s.\n    </div>\n  </div>\n\n  <!-- QUICK REVISION CHEAT SHEET -->\n  <div style=\"background: rgba(0, 198, 255, 0.05); border: 1.5px solid #00c6ff; border-radius: 12px; padding: 18px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #00c6ff; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Quick Revision Cheat Sheet</h2>\n    <p class=\"text-center\" style=\"color: #00c6ff; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Summary Formulae for Unit III: Laws of Motion</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; font-size: 14.5px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>• Newton's Second Law:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">F⃗ = m a⃗ = dp⃗ / dt<br>J⃗ = F⃗ Δt = Δp⃗</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>• Momentum Conservation:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">F_ext = 0 &nbsp; ⇒ &nbsp; m₁ v₁ + m₂ v₂ = Const<br>Recoil velocity v_r = - (m/M) v</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #00c6ff; border-radius: 6px;\">\n        <b style='color: #00c6ff; display: block; margin-bottom: 4px;'>• Banking &amp; Friction:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">v_optimum = √(g r tanθ)<br>f_s ≤ μ_s N &nbsp;|&nbsp; f_k = μ_k N</span>\n      </div>\n    </div>\n  </div>\n\n</div>\n";

export const c11Phy4HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n  \n  <div style=\"text-align: center; margin-bottom: 25px; border-bottom: 2px solid #00c6ff; padding-bottom: 10px;\">\n    <h2 style=\"color: #00c6ff; margin: 0; font-size: 22px; font-weight: bold; text-align: center !important;\">NCERT & Master Solutions Guide</h2>\n    <p style=\"color: #B0BEC5; margin: 5px 0 0 0; font-size: 15px; text-align: center !important;\">Unit IV: Work, Energy and Power — 100 Master Practice Questions (Theoretical & Numerical)</p>\n  </div>\n<h3 style=\"color: #00c6ff; border-left: 4px solid #00c6ff; padding-left: 10px; margin-top: 25px;\">Part A: Multiple Choice Questions (Q1 - Q25)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q1: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Work done on a body is maximum when the angle θ between force and displacement is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 0°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 45°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 90°</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 180°</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">a) 0°</span></b><br>W = F s cos θ. W is maximum when cos θ = 1, which occurs at θ = 0°.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q2: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The work done by centripetal force on a body moving in a circular path is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Positive</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Negative</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Zero</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Infinite</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) Zero</span></b><br>Centripetal force is always perpendicular to displacement (θ = 90°), so W = F s cos 90° = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q3: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A body of mass 2 kg moving at 4 m s<sup>-1</sup> has kinetic energy of:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 4 J</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 8 J</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 16 J</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 32 J</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) 16 J</span></b><br>E<sub>k</sub> = 1/2 m v<sup>2</sup> = 1/2 (2) (4<sup>2</sup>) = 16 Joules.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q4: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If linear momentum of a body is doubled, its kinetic energy increases by a factor of:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 2</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 4</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 8</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Remains same</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) 4</span></b><br>E<sub>k</sub> = p<sup>2</sup> / (2m). If p becomes 2p, E<sub>k</sub>' = (2p)<sup>2</sup> / (2m) = 4 E<sub>k</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q5: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The area under Force-Displacement (F-x) graph represents:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Power</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Acceleration</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Work done</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Momentum</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) Work done</span></b><br>Area under F-x graph = ∫ F dx = Work done.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q6: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which of the following is a non-conservative force?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Gravitational force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Electrostatic force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Frictional force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Spring force</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) Frictional force</span></b><br>Friction is a non-conservative force because work done against friction depends on path length and is non-recoverable.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q7: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Work done over a complete closed loop by a conservative force is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Maximum</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Zero</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Infinity</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Negative</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) Zero</span></b><br>For a conservative force, ∮ F · dr = 0 over any closed loop.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q8: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The elastic potential energy stored in a spring stretched by distance x is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) k x</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 1/2 k x</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 1/2 k x<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) k x<sup>2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) 1/2 k x<sup>2</sup></span></b><br>U<sub>s</sub> = 1/2 k x<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q9: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">1 Horsepower (hp) is equal to how many Watts?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 500 W</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 746 W</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 1000 W</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 3.6 × 10<sup>6</sup> W</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) 746 W</span></b><br>1 hp = 746 Watts.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q10: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">1 Kilowatt-hour (kWh) in Joules is equal to:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 3.6 × 10<sup>5</sup> J</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 3.6 × 10<sup>6</sup> J</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 10<sup>3</sup> J</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 746 J</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) 3.6 × 10<sup>6</sup> J</span></b><br>1 kWh = 1000 W × 3600 s = 3.6 × 10<sup>6</sup> Joules.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q11: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">In a perfectly elastic collision, which quantity is conserved?<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Kinetic energy only</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Linear momentum only</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Both linear momentum and kinetic energy</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Neither momentum nor kinetic energy</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) Both linear momentum and kinetic energy</span></b><br>Perfectly elastic collisions strictly conserve both linear momentum and kinetic energy.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q12: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The coefficient of restitution e for a perfectly inelastic collision is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 1</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 0</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 0.5</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Infinite</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) 0</span></b><br>In a perfectly inelastic collision, colliding bodies stick together (v<sub>1</sub> = v<sub>2</sub>), so e = (v<sub>2</sub> - v<sub>1</sub>)/(u<sub>1</sub> - u<sub>2</sub>) = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q13: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Minimum speed required at lowest point to complete a vertical circular loop of radius r is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) √(g r)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) √(3 g r)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) √(5 g r)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) √(7 g r)</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) √(5 g r)</span></b><br>At the bottom of vertical circle, critical speed v<sub>L</sub> = √(5 g r).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q14: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The minimum speed required at the apex (highest point) of a vertical circular loop of radius r is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) √(g r)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) √(2 g r)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) √(3 g r)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) √(5 g r)</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">a) √(g r)</span></b><br>At top of vertical loop, critical speed v<sub>H</sub> = √(g r).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q15: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Tension difference between lowest point T<sub>L</sub> and highest point T<sub>H</sub> in vertical circular motion is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 2 m g</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 4 m g</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 6 m g</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 8 m g</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) 6 m g</span></b><br>T<sub>L</sub> - T<sub>H</sub> = 6 m g.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q16: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">When two equal masses undergo 1D head-on elastic collision, their final velocities:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Become zero</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Double</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Swap completely</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Become equal to average speed</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) Swap completely</span></b><br>For equal masses (m<sub>1</sub> = m<sub>2</sub>) in 1D elastic collision, v<sub>1</sub> = u<sub>2</sub> and v<sub>2</sub> = u<sub>1</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q17: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Work done by friction force on a sliding block is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Always positive</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Always negative</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Always zero</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Undefined</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) Always negative</span></b><br>Friction acts at 180° to displacement (cos 180° = -1), making work done negative.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q18: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If spring constant k is doubled for same stretch x, stored potential energy becomes:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Halved</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Doubled</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 4 times</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Unchanged</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) Doubled</span></b><br>U = 1/2 k x<sup>2</sup>. Direct linear dependence on k.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q19: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 50 kg man climbs 20 steps of height 0.2 m each in 10 s. Power output is (g = 10 m s<sup>-2</sup>):<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 100 W</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 200 W</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 400 W</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 500 W</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) 200 W</span></b><br>Height h = 20 × 0.2 = 4 m. Work W = m g h = 50 × 10 × 4 = 2000 J. Power P = W / t = 2000 / 10 = 200 W.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q20: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Work done by a force F = 3 î + 4 ĵ N for displacement s = 5 î m is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 7 J</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 12 J</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 15 J</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 20 J</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) 15 J</span></b><br>W = F · s = (3)(5) + (4)(0) = 15 Joules.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q21: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Dimensions of Power are:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) [M L T<sup>-2</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) [M L<sup>2</sup> T<sup>-2</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) [M L<sup>2</sup> T<sup>-3</sup>]</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) [M L<sup>-1</sup> T<sup>-2</sup>]</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) [M L<sup>2</sup> T<sup>-3</sup>]</span></b><br>Power = Work / Time = [M L<sup>2</sup> T<sup>-2</sup>] / [T] = [M L<sup>2</sup> T<sup>-3</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q22: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A bullet embeds into a wooden block resting on smooth surface. The collision is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Perfectly elastic</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Perfectly inelastic</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Partially elastic</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Conservative</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) Perfectly inelastic</span></b><br>Since bullet embeds and moves with block at common velocity (e = 0), collision is perfectly inelastic.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q23: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The rate of doing work is called:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Force</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Energy</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Power</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Momentum</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) Power</span></b><br>Power P = dW/dt.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q24: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Potential energy curve U(x) and force F(x) are related by:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) F = dU / dx</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) F = - dU / dx</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) F = U<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) F = ∫ U dx</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">b) F = - dU / dx</span></b><br>For conservative force, F = - dU/dx.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q25: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A force F = 10 N moves a block at constant velocity 5 m s<sup>-1</sup> in its direction. Power is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 2 W</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 15 W</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 50 W</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 100 W</div>\n  </div></div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #00c6ff;\">c) 50 W</span></b><br>P = F v = 10 × 5 = 50 W.\n    </div>\n  </div><h3 style=\"color: #00c6ff; border-left: 4px solid #00c6ff; padding-left: 10px; margin-top: 35px;\">Part B: Very Short Answer Questions (Q26 - Q55)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q26: Define Work</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define work in physics and state its SI unit.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Work is done when a force causes displacement along or opposite to force direction: W = F · s = |F||s| cos θ. SI unit: Joule (J).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q27: Positive Work Condition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">When is work done said to be positive? Give one example.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Work is positive when force and displacement act in same direction (0° ≤ θ < 90°). Example: Work done by gravitational force on falling apple.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q28: Negative Work Condition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">When is work done negative? Give one example.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Work is negative when force opposes displacement (90° < θ ≤ 180°). Example: Work done by friction on sliding block.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q29: Zero Work Condition</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State two conditions under which work done is zero.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. Displacement is zero (s = 0).<br>2. Force is perpendicular to displacement (θ = 90°).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q30: Work Done by Variable Force Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for work done by a variable force F(x).</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      W = ∫<sub>x1</sub><sup>x2</sup> F(x) dx = Area under F-x graph.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q31: Define Kinetic Energy</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define kinetic energy and state its formula.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Kinetic energy is energy possessed by a body due to its motion: E<sub>k</sub> = 1/2 m v<sup>2</sup> = p<sup>2</sup> / (2m).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q32: State Work-Energy Theorem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the Work-Energy Theorem.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Work-Energy Theorem states that net work done by all forces on a body equals net change in its kinetic energy: W<sub>net</sub> = ΔE<sub>k</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q33: Define Power</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define power and state its SI unit.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Power is rate of doing work or energy transfer per unit time: P = dW/dt = F · v. SI unit: Watt (W).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q34: Define Horsepower</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the relation between Horsepower and Watt.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1 Horsepower (hp) = 746 Watts.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q35: Define Kilowatt-Hour</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define 1 kilowatt-hour (kWh) and convert it into Joules.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1 kWh is commercial unit of energy consumed by 1 kW appliance in 1 hour. 1 kWh = 3.6 × 10<sup>6</sup> Joules.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q36: Define Conservative Force</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define a conservative force with two examples.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A force is conservative if work done by it depends only on initial/final positions and ∮ F · dr = 0 (e.g. Gravitational force, Electrostatic force).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q37: Define Non-Conservative Force</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define a non-conservative force with two examples.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A force is non-conservative if work done depends on path length (e.g. Frictional force, Viscous drag).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q38: Define Gravitational Potential Energy</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for gravitational potential energy near Earth surface.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      U = m g h (where h is height above reference plane).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q39: Spring Potential Energy Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for potential energy stored in a stretched spring.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      U<sub>s</sub> = 1/2 k x<sup>2</sup> (where k is spring constant and x is elongation).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q40: Conservation of Mechanical Energy Statement</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Law of Conservation of Mechanical Energy.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Total mechanical energy E = E<sub>k</sub> + U of an isolated system remains constant under conservative forces.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q41: Define Elastic Collision</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is an elastic collision?</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      An elastic collision is one in which both total linear momentum AND total kinetic energy are strictly conserved.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q42: Define Inelastic Collision</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is an inelastic collision?</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      An inelastic collision is one in which linear momentum is conserved, but kinetic energy is partially lost.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q43: Define Perfectly Inelastic Collision</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is a perfectly inelastic collision?</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A collision where colliding bodies stick together after impact and move with a common final velocity (e = 0).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q44: Coefficient of Restitution Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for coefficient of restitution e.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      e = (v<sub>2</sub> - v<sub>1</sub>) / (u<sub>1</sub> - u<sub>2</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q45: Coefficient of Restitution Values</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State values of e for elastic and perfectly inelastic collisions.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      For elastic collision e = 1; for perfectly inelastic collision e = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q46: Critical Speed at Lowest Point of Vertical Circle</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State minimum speed at bottom to complete vertical circle of radius r.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      v<sub>L</sub> = √(5 g r).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q47: Critical Speed at Apex of Vertical Circle</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State minimum speed at top to complete vertical circle of radius r.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      v<sub>H</sub> = √(g r).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q48: Tension Difference in Vertical Circle</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State tension difference T<sub>L</sub> - T<sub>H</sub> in vertical circular motion.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      T<sub>L</sub> - T<sub>H</sub> = 6 m g.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q49: Relation between F and U</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Write differential relation between conservative force F and potential energy U.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      F = - dU / dx.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q50: Spring Force Formula (Hooke's Law)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Hooke's Law for spring restoring force.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      F<sub>s</sub> = - k x.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q51: Work Done by Centripetal Force</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Why is work done by centripetal force always zero?</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Because centripetal force acts perpendicular to instantaneous displacement (θ = 90°), cos 90° = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q52: Exchange of Velocities in 1D Elastic Collision</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Under what condition do colliding bodies exchange velocities in 1D elastic collision?</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      When two colliding bodies have equal masses (m<sub>1</sub> = m<sub>2</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q53: Dimension of Work</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State dimensional formula of Work.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Dimensions of Work = [M<sup>1</sup> L<sup>2</sup> T<sup>-2</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q54: Dimension of Power</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State dimensional formula of Power.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Dimensions of Power = [M<sup>1</sup> L<sup>2</sup> T<sup>-3</sup>].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q55: Light vs Heavy Body Momentum Relation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If light body A and heavy body B have equal kinetic energy, which has larger momentum?</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Heavy body B has larger momentum because p = √(2 m E<sub>k</sub>), so p ∝ √m for constant E<sub>k</sub>.\n    </div>\n  </div><h3 style=\"color: #00c6ff; border-left: 4px solid #00c6ff; padding-left: 10px; margin-top: 35px;\">Part C: Short Answer Questions (Q56 - Q85)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q56: Work Done by Constant Force Vector Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Force F = 2 î - 3 ĵ + 4 k̂ N displaces a body from r<sub>1</sub> = î + 2 ĵ + k̂ m to r<sub>2</sub> = 3 î + 4 ĵ + 5 k̂ m. Calculate work done.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Displacement s = r<sub>2</sub> - r<sub>1</sub> = (3-1)î + (4-2)ĵ + (5-1)k̂ = 2 î + 2 ĵ + 4 k̂ m.<br>Work W = F · s = (2)(2) + (-3)(2) + (4)(4) = 4 - 6 + 16 = <b>14 Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q57: Work Done by Variable Force F(x) Integral Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A variable force F(x) = (3 x<sup>2</sup> + 2 x) N acts on a particle from x = 1 m to x = 3 m. Calculate work done.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      W = ∫<sub>1</sub><sup>3</sup> (3 x<sup>2</sup> + 2 x) dx = [x<sup>3</sup> + x<sup>2</sup>]<sub>1</sub><sup>3</sup>.<br>At x = 3: 3<sup>3</sup> + 3<sup>2</sup> = 27 + 9 = 36.<br>At x = 1: 1<sup>3</sup> + 1<sup>2</sup> = 1 + 1 = 2.<br>W = 36 - 2 = <b>34 Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q58: Derive Work-Energy Theorem for Constant Force</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive Work-Energy Theorem W = 1/2 m v<sup>2</sup> - 1/2 m u<sup>2</sup> for constant force.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      From equation of motion v<sup>2</sup> - u<sup>2</sup> = 2 a s ⇒ s = (v<sup>2</sup> - u<sup>2</sup>) / (2 a).<br>Work done W = F × s = (m a) × [ (v<sup>2</sup> - u<sup>2</sup>) / (2 a) ].<br>Canceling acceleration a:<br><b>W = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> m v<sup>2</sup> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> m u<sup>2</sup> = ΔE<sub>k</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q59: Derive Potential Energy of Stretched Spring</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive formula U<sub>s</sub> = 1/2 k x<sup>2</sup> for potential energy of spring.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Restoring force F<sub>s</sub> = -k x. External force needed F<sub>ext</sub> = k x.<br>Work done to stretch spring by small dx: dW = F<sub>ext</sub> dx = k x dx.<br>Total work U<sub>s</sub> = ∫<sub>0</sub><sup>x</sup> k x' dx' = k [ x'<sup>2</sup> / 2 ]<sub>0</sub><sup>x</sup> = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> k x<sup>2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q60: Prove Conservative Force Work in Closed Loop is Zero</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove that work done by gravity over a closed round trip is zero.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Body of mass m lifted to height h: W<sub>up</sub> = m g h cos 180° = -m g h.<br>Body falls back from height h: W<sub>down</sub> = m g h cos 0° = +m g h.<br>Total work W<sub>total</sub> = W<sub>up</sub> + W<sub>down</sub> = -m g h + m g h = <b>0</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q61: Spring Extension Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A spring of spring constant k = 200 N m<sup>-1</sup> is compressed by 0.1 m. Calculate stored elastic potential energy.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      U<sub>s</sub> = 1/2 k x<sup>2</sup> = 1/2 (200) (0.1)<sup>2</sup> = 100 × 0.01 = <b>1 Joule</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q62: Power Output of Engine Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">An engine pumps 1000 kg of water to a height of 10 m in 20 s. Calculate power output in Watts and hp (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Work W = m g h = 1000 × 10 × 10 = 100,000 J.<br>Power P = W / t = 100,000 / 20 = <b>5000 Watts (5 kW)</b>.<br>In hp: P = 5000 / 746 = <b>6.7 Horsepower</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q63: Light vs Heavy Body Speed for Equal Momentum</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If light body m<sub>1</sub> and heavy body m<sub>2</sub> (m<sub>2</sub> > m<sub>1</sub>) have equal linear momentum p, show that light body has larger kinetic energy.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      E<sub>k</sub> = p<sup>2</sup> / (2 m). Since p is same for both:<br>E<sub>k1</sub> / E<sub>k2</sub> = m<sub>2</sub> / m<sub>1</sub>.<br>Since m<sub>2</sub> > m<sub>1</sub>, E<sub>k1</sub> > E<sub>k2</sub>. <b>Lighter body has larger kinetic energy!</b>\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q64: Stopping Distance Comparison Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Two cars of masses m<sub>1</sub> and m<sub>2</sub> moving at same velocity v apply identical braking force F. Compare stopping distances.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      By Work-Energy Theorem: F × s = 1/2 m v<sup>2</sup> ⇒ s = (m v<sup>2</sup>) / (2 F).<br>For same v and F: s ∝ m. <b>Heavier car requires larger stopping distance!</b>\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q65: Kinetic Energy Loss in 1D Inelastic Collision Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expression for kinetic energy loss when mass m<sub>1</sub> moving at u<sub>1</sub> collides with stationary m<sub>2</sub> (u<sub>2</sub> = 0) perfectly inelastically.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Common velocity V = (m<sub>1</sub> u<sub>1</sub>) / (m<sub>1</sub> + m<sub>2</sub>).<br>Initial K.E. E<sub>k1</sub> = 1/2 m<sub>1</sub> u<sub>1</sub><sup>2</sup>.<br>Final K.E. E<sub>k2</sub> = 1/2 (m<sub>1</sub> + m<sub>2</sub>) V<sup>2</sup> = 1/2 (m<sub>1</sub> + m<sub>2</sub>) [ m<sub>1</sub> u<sub>1</sub> / (m<sub>1</sub> + m<sub>2</sub>) ]<sup>2</sup> = 1/2 [ m<sub>1</sub><sup>2</sup> u<sub>1</sub><sup>2</sup> / (m<sub>1</sub> + m<sub>2</sub>) ].<br>Loss ΔE<sub>k</sub> = E<sub>k1</sub> - E<sub>k2</sub> = 1/2 m<sub>1</sub> u<sub>1</sub><sup>2</sup> [ 1 - m<sub>1</sub> / (m<sub>1</sub> + m<sub>2</sub>) ] = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>1</sub> m<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> ] u<sub>1</sub><sup>2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q66: Vertical Circle Tension at Lowest vs Highest Point Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expressions for string tension at lowest point T<sub>L</sub> and highest point T<sub>H</sub> in vertical circular motion.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      At lowest point L: T<sub>L</sub> - mg = m v<sub>L</sub><sup>2</sup> / r ⇒ T<sub>L</sub> = mg + m v<sub>L</sub><sup>2</sup> / r.<br>For critical loop v<sub>L</sub> = √(5 gr): T<sub>L</sub> = mg + m(5 gr)/r = <b>6 mg</b>.<br><br>At highest point H: T<sub>H</sub> + mg = m v<sub>H</sub><sup>2</sup> / r ⇒ T<sub>H</sub> = m v<sub>H</sub><sup>2</sup> / r - mg.<br>For critical loop v<sub>H</sub> = √(gr): T<sub>H</sub> = m(gr)/r - mg = <b>0</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q67: 1D Elastic Collision Velocity Exchange Proof</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove that when two equal masses collide elastically in 1D, they completely swap their velocities.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Velocity formulas:<br>v<sub>1</sub> = [ (m<sub>1</sub> - m<sub>2</sub>)/(m<sub>1</sub> + m<sub>2</sub>) ] u<sub>1</sub> + [ 2 m<sub>2</sub> / (m<sub>1</sub> + m<sub>2</sub>) ] u<sub>2</sub>.<br>v<sub>2</sub> = [ 2 m<sub>1</sub> / (m<sub>1</sub> + m<sub>2</sub>) ] u<sub>1</sub> + [ (m<sub>2</sub> - m<sub>1</sub>)/(m<sub>1</sub> + m<sub>2</sub>) ] u<sub>2</sub>.<br>Substitute m<sub>1</sub> = m<sub>2</sub> = m:<br>v<sub>1</sub> = (0) u<sub>1</sub> + (2m / 2m) u<sub>2</sub> = <b>u<sub>2</sub></b>.<br>v<sub>2</sub> = (2m / 2m) u<sub>1</sub> + (0) u<sub>2</sub> = <b>u<sub>1</sub></b>. Velocities are swapped!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q68: Rain Drop Terminal Velocity & Work Done</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A raindrop of mass 1 g falls from height 1 km and hits ground with 50 m s<sup>-1</sup>. Calculate work done by gravity and air resistance (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Work by gravity W<sub>g</sub> = m g h = 0.001 × 10 × 1000 = <b>10 Joules</b>.<br>Net K.E. change ΔE<sub>k</sub> = 1/2 m v<sup>2</sup> = 1/2 (0.001) (50<sup>2</sup>) = 0.5 × 2.5 = <b>1.25 Joules</b>.<br>By Work-Energy Theorem: W<sub>g</sub> + W<sub>air</sub> = ΔE<sub>k</sub> ⇒ 10 + W<sub>air</sub> = 1.25.<br><b>W<sub>air</sub> = 1.25 - 10 = -8.75 Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q69: Potential Energy Function Force Calculation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Potential energy function U(x) = 5 x<sup>2</sup> - 4 x J. Find force F(x) and equilibrium position.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Force F(x) = - dU/dx = - d/dx (5 x<sup>2</sup> - 4 x) = <b>-(10 x - 4) = 4 - 10 x</b>.<br>At equilibrium F(x) = 0 ⇒ 4 - 10 x = 0 ⇒ <b>x = 0.4 m</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q70: Colliding Masses Common Velocity Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 2 kg mass moving at 6 m s<sup>-1</sup> collides with a 4 kg mass moving at 3 m s<sup>-1</sup> in same direction and sticks. Find common speed.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Conservation of momentum: m<sub>1</sub> u<sub>1</sub> + m<sub>2</sub> u<sub>2</sub> = (m<sub>1</sub> + m<sub>2</sub>) V.<br>2(6) + 4(3) = (2 + 4) V ⇒ 12 + 12 = 6 V ⇒ 24 = 6 V.<br><b>Common Speed V = 4 m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q71: Calculate kWh Energy Consumption</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A house runs 4 bulbs of 100 W for 5 h daily and 1 electric heater of 1000 W for 2 h daily. Calculate total energy in kWh consumed in 30 days.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Daily energy bulbs = 4 × 100 W × 5 h = 2000 Wh = 2 kWh.<br>Daily energy heater = 1000 W × 2 h = 2000 Wh = 2 kWh.<br>Total daily energy = 2 + 2 = 4 kWh.<br>Total 30 days energy = 4 × 30 = <b>120 kWh (Units)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q72: Conservation of Energy Free Fall Proof</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove conservation of mechanical energy for a body of mass m falling freely under gravity from height h.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Top (A):</b> E<sub>k</sub> = 0, U = mgh ⇒ E<sub>A</sub> = mgh.<br><b>Middle (B, fallen x):</b> v<sup>2</sup> = 2gx ⇒ E<sub>kB</sub> = 1/2 m(2gx) = mgx, U<sub>B</sub> = mg(h-x) ⇒ E<sub>B</sub> = mgx + mgh - mgx = mgh.<br><b>Bottom (C):</b> v<sup>2</sup> = 2gh ⇒ E<sub>kC</sub> = mgh, U<sub>C</sub> = 0 ⇒ E<sub>C</sub> = mgh.<br><b>E<sub>A</sub> = E<sub>B</sub> = E<sub>C</sub> = mgh (Conserved!)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q73: Power Required to Move Car against Friction</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A car of 1000 kg moves up an incline of 1 in 20 at constant 18 km h<sup>-1</sup>. Friction is 100 N. Find engine power (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Speed v = 18 × (5/18) = 5 m/s. sin θ = 1/20.<br>Parallel gravity component = mg sin θ = 1000 × 10 × (1/20) = 500 N.<br>Total opposing force F = 500 + 100 (friction) = 600 N.<br>Engine Power P = F × v = 600 × 5 = <b>3000 Watts (3 kW)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q74: Spring Compressed by Falling Mass Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 2 kg mass falls from height 0.4 m onto a vertical spring of k = 1960 N m<sup>-1</sup>. Calculate max compression x (g = 9.8 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Loss in gravitational PE = Gain in spring PE.<br>m g (h + x) = 1/2 k x<sup>2</sup> ⇒ 2(9.8)(0.4 + x) = 1/2 (1960) x<sup>2</sup>.<br>19.6 (0.4 + x) = 980 x<sup>2</sup> ⇒ 7.84 + 19.6 x = 980 x<sup>2</sup>.<br>980 x<sup>2</sup> - 19.6 x - 7.84 = 0 ⇒ 50 x<sup>2</sup> - x - 0.4 = 0.<br>Solving quadratic: <b>x = 0.1 m (10 cm)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q75: Coefficient of Restitution Bounce Height Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A ball dropped from height h rebound to height h'. Express e in terms of h and h'.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Impact velocity u = √(2 g h), rebound velocity v = √(2 g h').<br>e = v / u = √(2 g h') / √(2 g h) = <b>√(h' / h)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q76: Elastic Collision 2D Equations Setup</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State 3 scalar equations governing a 2D oblique elastic collision between mass m<sub>1</sub> and m<sub>2</sub>.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. <b>x-momentum:</b> m<sub>1</sub> u<sub>1</sub> = m<sub>1</sub> v<sub>1</sub> cos θ<sub>1</sub> + m<sub>2</sub> v<sub>2</sub> cos θ<sub>2</sub>.<br>2. <b>y-momentum:</b> 0 = m<sub>1</sub> v<sub>1</sub> sin θ<sub>1</sub> - m<sub>2</sub> v<sub>2</sub> sin θ<sub>2</sub>.<br>3. <b>Kinetic Energy:</b> 1/2 m<sub>1</sub> u<sub>1</sub><sup>2</sup> = 1/2 m<sub>1</sub> v<sub>1</sub><sup>2</sup> + 1/2 m<sub>2</sub> v<sub>2</sub><sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q77: Work Done Lifting Hanging Rope Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A uniform rope of mass M and length L lies on floor. Calculate work needed to lift one end to height L.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Center of gravity of lifted rope rises to height L/2.<br>Work W = M g h<sub>cg</sub> = M g (L / 2) = <b>1/2 M g L</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q78: Kinetic Energy Ratio from Velocity Ratio</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Two bodies have mass ratio 1:4 and kinetic energy ratio 4:1. Calculate ratio of their linear momenta.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      p = √(2 m E<sub>k</sub>).<br>p<sub>1</sub> / p<sub>2</sub> = √[ (m<sub>1</sub> E<sub>k1</sub>) / (m<sub>2</sub> E<sub>k2</sub>) ] = √[ (1 × 4) / (4 × 1) ] = √1 = <b>1:1 (Equal momenta!)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q79: Conservative Force Gradient Property</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Show that F = - dU/dx implies force points in direction of decreasing potential energy.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Since F = - dU/dx, if dU/dx is positive (U increases with x), F is negative (points in -x direction). Thus force always drives system toward lower potential energy!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q80: Power delivered by Constant Force to Mass m from Rest</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A constant force F acts on mass m starting from rest. Derive power P as a function of time t.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Acceleration a = F / m. Velocity at time t: v = a t = (F / m) t.<br>Instantaneous Power P = F · v = F × (F / m) t = <b>(F<sup>2</sup> / m) t</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q81: Work-Energy Theorem Application to Bullet</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 10 g bullet moving at 200 m s<sup>-1</sup> penetrates 4 cm into mud block before stopping. Find average retarding force.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Initial K.E. = 1/2 (0.01) (200<sup>2</sup>) = 0.5 × 0.01 × 40000 = 200 Joules.<br>By Work-Energy Theorem: W = -F × s = -200 J.<br>F × 0.04 = 200 ⇒ F = 200 / 0.04 = <b>5000 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q82: Collision of Pendulum Bob Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A pendulum bob of mass m released from height h collides elastically with identical stationary mass m on table. Find height to which table mass rises.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Bob reaches bottom with speed u = √(2 gh). In 1D elastic collision between equal masses, velocities swap.<br>Table mass acquires speed v = √(2 gh) and rises to same height <b>h</b>!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q83: Stable vs Unstable Equilibrium from U(x)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain conditions for stable, unstable, and neutral equilibrium using d<sup>2</sup>U/dx<sup>2</sup>.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      At equilibrium dU/dx = 0.<br>1. <b>Stable:</b> d<sup>2</sup>U/dx<sup>2</sup> > 0 (U is minimum).<br>2. <b>Unstable:</b> d<sup>2</sup>U/dx<sup>2</sup> < 0 (U is maximum).<br>3. <b>Neutral:</b> d<sup>2</sup>U/dx<sup>2</sup> = 0 (U is constant).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q84: Work Done by Force F = (x i + y j)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Calculate work done by force F = x î + y ĵ N moving particle from (0,0) to (2,3) m.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      W = ∫<sub>0</sub><sup>2</sup> x dx + ∫<sub>0</sub><sup>3</sup> y dy = [x<sup>2</sup>/2]<sub>0</sub><sup>2</sup> + [y<sup>2</sup>/2]<sub>0</sub><sup>3</sup> = 2 + 4.5 = <b>6.5 Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q85: Energy Conserved in Spring-Block System</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove total energy E = 1/2 k A<sup>2</sup> for a block of mass m oscillating on spring of constant k with amplitude A.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      At extreme displacement x = A: v = 0 ⇒ E<sub>k</sub> = 0, U<sub>s</sub> = 1/2 k A<sup>2</sup>.<br>Total mechanical energy E = E<sub>k</sub> + U<sub>s</sub> = <b>1/2 k A<sup>2</sup></b> (Constant throughout oscillation).\n    </div>\n  </div><h3 style=\"color: #00c6ff; border-left: 4px solid #00c6ff; padding-left: 10px; margin-top: 35px;\">Part D: Long Answer Questions (Q86 - Q100)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q86: Work-Energy Theorem Full Calculus Proof & Applications</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State and prove the Work-Energy Theorem for (i) constant force, and (ii) variable force using calculus. Discuss its applications.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Statement:</b> Net work done by all forces on a body equals change in its kinetic energy: W<sub>net</sub> = ΔE<sub>k</sub>.<br><br><b>(i) Proof for Constant Force:</b><br>v<sup>2</sup> - u<sup>2</sup> = 2 a s ⇒ s = (v<sup>2</sup> - u<sup>2</sup>)/(2a).<br>W = F s = m a [ (v<sup>2</sup> - u<sup>2</sup>)/(2a) ] = <b>1/2 m v<sup>2</sup> - 1/2 m u<sup>2</sup></b>.<br><br><b>(ii) Proof for Variable Force:</b><br>F = m a = m (dv/dt) = m v (dv/dx).<br>W = ∫<sub>x1</sub><sup>x2</sup> F dx = ∫<sub>x1</sub><sup>x2</sup> (m v dv/dx) dx = m ∫<sub>u</sub><sup>v</sup> v dv.<br>W = m [ v<sup>2</sup> / 2 ]<sub>u</sub><sup>v</sup> = <b>1/2 m v<sup>2</sup> - 1/2 m u<sup>2</sup> = ΔE<sub>k</sub></b>.<br><br><b>Applications:</b> Used to calculate stopping distances of vehicles, bullet penetration depth, and speed of objects under non-uniform forces.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q87: Complete Theory & Derivation of Potential Energy of Spring</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define spring constant k. Derive the expression for elastic potential energy of a stretched spring U<sub>s</sub> = 1/2 k x<sup>2</sup>. Plot U<sub>s</sub> and E<sub>k</sub> vs position x.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Spring Constant k:</b> Restoring force per unit elongation F<sub>s</sub> = -k x.<br><br><b>Derivation:</b><br>To stretch spring by small displacement dx', external force required F<sub>ext</sub> = k x'.<br>Small work done dW = k x' dx'.<br>Total work done to stretch from x = 0 to x:<br>W = ∫<sub>0</sub><sup>x</sup> k x' dx' = k [ x'<sup>2</sup> / 2 ]<sub>0</sub><sup>x</sup> = <b>1/2 k x<sup>2</sup></b>.<br>This work is stored as potential energy <b>U<sub>s</sub> = 1/2 k x<sup>2</sup></b>.<br><br><b>Energy Graph Analysis:</b><br>- At equilibrium x = 0: U<sub>s</sub> = 0, E<sub>k</sub> = E<sub>max</sub> = 1/2 k A<sup>2</sup>.<br>- At extremes x = ±A: U<sub>s</sub> = 1/2 k A<sup>2</sup>, E<sub>k</sub> = 0.<br>- Total mechanical energy E = E<sub>k</sub> + U<sub>s</sub> = 1/2 k A<sup>2</sup> is a horizontal straight line.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q88: Complete Derivation of 1D Elastic Collision Final Velocities</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive mathematical expressions for final velocities v<sub>1</sub> and v<sub>2</sub> of two masses m<sub>1</sub> and m<sub>2</sub> undergoing 1D head-on elastic collision. Discuss 3 special cases.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Consider masses m<sub>1</sub> and m<sub>2</sub> moving with initial velocities u<sub>1</sub> and u<sub>2</sub>.<br><br><b>Momentum Conservation:</b> m<sub>1</sub> u<sub>1</sub> + m<sub>2</sub> u<sub>2</sub> = m<sub>1</sub> v<sub>1</sub> + m<sub>2</sub> v<sub>2</sub> &nbsp; ⇒ &nbsp; m<sub>1</sub> (u<sub>1</sub> - v<sub>1</sub>) = m<sub>2</sub> (v<sub>2</sub> - u<sub>2</sub>) ---(1)<br><b>Kinetic Energy Conservation:</b> 1/2 m<sub>1</sub> u<sub>1</sub><sup>2</sup> + 1/2 m<sub>2</sub> u<sub>2</sub><sup>2</sup> = 1/2 m<sub>1</sub> v<sub>1</sub><sup>2</sup> + 1/2 m<sub>2</sub> v<sub>2</sub><sup>2</sup> &nbsp; ⇒ &nbsp; m<sub>1</sub> (u<sub>1</sub><sup>2</sup> - v<sub>1</sub><sup>2</sup>) = m<sub>2</sub> (v<sub>2</sub><sup>2</sup> - u<sub>2</sub><sup>2</sup>) ---(2)<br>Dividing (2) by (1): u<sub>1</sub> + v<sub>1</sub> = v<sub>2</sub> + u<sub>2</sub> &nbsp; ⇒ &nbsp; <b>u<sub>1</sub> - u<sub>2</sub> = v<sub>2</sub> - v<sub>1</sub></b> (Relative velocity of approach = Relative velocity of separation).<br><br><b>Solving for v<sub>1</sub> and v<sub>2</sub>:</b><br><b>v<sub>1</sub> = [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>1</sub> - m<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> ] u<sub>1</sub> + [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 m<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> ] u<sub>2</sub></b><br><b>v<sub>2</sub> = [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 m<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> ] u<sub>1</sub> + [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>2</sub> - m<sub>1</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> ] u<sub>2</sub></b><br><br><b>Special Cases:</b><br>1. m<sub>1</sub> = m<sub>2</sub>: v<sub>1</sub> = u<sub>2</sub>, v<sub>2</sub> = u<sub>1</sub> (Velocity Swap).<br>2. m<sub>1</sub> >> m<sub>2</sub> and u<sub>2</sub> = 0: v<sub>1</sub> ≈ u<sub>1</sub>, v<sub>2</sub> ≈ 2 u<sub>1</sub>.<br>3. m<sub>1</sub> << m<sub>2</sub> and u<sub>2</sub> = 0: v<sub>1</sub> ≈ -u<sub>1</sub>, v<sub>2</sub> ≈ 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q89: Complete Theory & Derivation of Motion in a Vertical Circle</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive minimum velocities required at bottom, middle, and top of a vertical circular loop of radius r for a body tied to a string to complete the loop. Find tension difference T<sub>L</sub> - T<sub>H</sub>.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let body of mass m be tied to string of radius r.<br><br><b>(i) Apex (Top H):</b><br>T<sub>H</sub> + mg = m v<sub>H</sub><sup>2</sup> / r. For critical loop T<sub>H</sub> ≥ 0 ⇒ <b>v<sub>H, min</sub> = √(g r)</b>.<br><br><b>(ii) Bottom (Lowest Point L):</b><br>Energy Conservation: 1/2 m v<sub>L</sub><sup>2</sup> = 1/2 m v<sub>H</sub><sup>2</sup> + m g (2 r).<br>v<sub>L</sub><sup>2</sup> = v<sub>H</sub><sup>2</sup> + 4 g r = g r + 4 g r = 5 g r ⇒ <b>v<sub>L, min</sub> = √(5 g r)</b>.<br>Tension T<sub>L</sub> = mg + m v<sub>L</sub><sup>2</sup> / r = mg + m(5 gr)/r = <b>6 m g</b>.<br><br><b>(iii) Midway Point (Horizontal M):</b><br>1/2 m v<sub>M</sub><sup>2</sup> = 1/2 m v<sub>H</sub><sup>2</sup> + m g r ⇒ v<sub>M</sub><sup>2</sup> = g r + 2 g r = 3 g r ⇒ <b>v<sub>M, min</sub> = √(3 g r)</b>.<br>Tension T<sub>M</sub> = m v<sub>M</sub><sup>2</sup> / r = <b>3 m g</b>.<br><br><b>Tension Difference:</b> T<sub>L</sub> - T<sub>H</sub> = 6 mg - 0 = <b>6 m g</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q90: Conservation of Mechanical Energy in Gravitational Field Proof</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove that total mechanical energy of a body of mass m thrown vertically upward with initial speed u remains constant at all points of its path.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let initial speed be u. Max height H = u<sup>2</sup> / (2g). Total energy E = 1/2 m u<sup>2</sup> = m g H.<br><br><b>1. Ground Level (A):</b> h = 0, v = u ⇒ E<sub>A</sub> = 1/2 m u<sup>2</sup> + 0 = <b>1/2 m u<sup>2</sup></b>.<br><b>2. Height y above ground (B):</b> v<sup>2</sup> = u<sup>2</sup> - 2gy.<br>E<sub>kB</sub> = 1/2 m (u<sup>2</sup> - 2gy) = 1/2 m u<sup>2</sup> - mgy.<br>U<sub>B</sub> = mgy.<br>E<sub>B</sub> = E<sub>kB</sub> + U<sub>B</sub> = (1/2 m u<sup>2</sup> - mgy) + mgy = <b>1/2 m u<sup>2</sup></b>.<br><b>3. Maximum Height H (C):</b> v = 0, h = H = u<sup>2</sup>/(2g).<br>E<sub>kC</sub> = 0, U<sub>C</sub> = mg [u<sup>2</sup>/(2g)] = 1/2 m u<sup>2</sup>.<br>E<sub>C</sub> = <b>1/2 m u<sup>2</sup></b>.<br><br><b>Conclusion:</b> E<sub>A</sub> = E<sub>B</sub> = E<sub>C</sub> = 1/2 m u<sup>2</sup> (Total mechanical energy is strictly conserved!).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q91: 1D Inelastic Collision Kinetic Energy Loss Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive common velocity V and expression for kinetic energy loss ΔE<sub>k</sub> in a 1D perfectly inelastic collision between mass m<sub>1</sub> (velocity u<sub>1</sub>) and m<sub>2</sub> (velocity u<sub>2</sub>).</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Common Velocity V:</b><br>By momentum conservation: m<sub>1</sub> u<sub>1</sub> + m<sub>2</sub> u<sub>2</sub> = (m<sub>1</sub> + m<sub>2</sub>) V ⇒ <b>V = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>1</sub> u<sub>1</sub> + m<sub>2</sub> u<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span></b>.<br><br><b>Kinetic Energy Loss ΔE<sub>k</sub>:</b><br>ΔE<sub>k</sub> = E<sub>k, initial</sub> - E<sub>k, final</sub> = [ 1/2 m<sub>1</sub> u<sub>1</sub><sup>2</sup> + 1/2 m<sub>2</sub> u<sub>2</sub><sup>2</sup> ] - 1/2 (m<sub>1</sub> + m<sub>2</sub>) V<sup>2</sup>.<br>Substitute V:<br>ΔE<sub>k</sub> = 1/2 m<sub>1</sub> u<sub>1</sub><sup>2</sup> + 1/2 m<sub>2</sub> u<sub>2</sub><sup>2</sup> - <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">(m<sub>1</sub> u<sub>1</sub> + m<sub>2</sub> u<sub>2</sub>)<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span>.<br>Simplifying terms:<br><b>ΔE<sub>k</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> [ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>1</sub> m<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> ] (u<sub>1</sub> - u<sub>2</sub>)<sup>2</sup></b>.<br>Since square term (u<sub>1</sub> - u<sub>2</sub>)<sup>2</sup> > 0, ΔE<sub>k</sub> is always positive, proving kinetic energy is strictly lost in inelastic collision!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q92: Work Done by Variable Force Curved F-x Integration Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A force F(x) = (2 + 3 x - x<sup>2</sup>) N acts on a 2 kg body causing displacement from x = 0 to x = 3 m. Calculate (i) work done, (ii) final velocity if initial velocity is 2 m s<sup>-1</sup>.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>(i) Work Done W:</b><br>W = ∫<sub>0</sub><sup>3</sup> (2 + 3 x - x<sup>2</sup>) dx = [ 2 x + 3 x<sup>2</sup>/2 - x<sup>3</sup>/3 ]<sub>0</sub><sup>3</sup>.<br>W = [ 2(3) + 3(9)/2 - 27/3 ] = [ 6 + 13.5 - 9 ] = <b>10.5 Joules</b>.<br><br><b>(ii) Final Velocity v:</b><br>By Work-Energy Theorem: W = 1/2 m v<sup>2</sup> - 1/2 m u<sup>2</sup>.<br>10.5 = 1/2 (2) v<sup>2</sup> - 1/2 (2) (2<sup>2</sup>) = v<sup>2</sup> - 4.<br>v<sup>2</sup> = 10.5 + 4 = 14.5.<br><b>v = √14.5 ≈ 3.81 m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q93: Spring Mass Oscillation & Energy Distribution Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 0.5 kg body attached to a horizontal spring of k = 50 N m<sup>-1</sup> is pulled 0.2 m from equilibrium and released from rest. Calculate (i) total mechanical energy, (ii) max speed, (iii) speed at x = 0.1 m.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Amplitude A = 0.2 m, m = 0.5 kg, k = 50 N m<sup>-1</sup>.<br><br><b>(i) Total Mechanical Energy E:</b><br>E = 1/2 k A<sup>2</sup> = 1/2 (50) (0.2<sup>2</sup>) = 25 × 0.04 = <b>1.0 Joule</b>.<br><br><b>(ii) Maximum Speed v<sub>max</sub> (at x = 0):</b><br>1/2 m v<sub>max</sub><sup>2</sup> = E ⇒ 1/2 (0.5) v<sub>max</sub><sup>2</sup> = 1.0 ⇒ 0.25 v<sub>max</sub><sup>2</sup> = 1.0 ⇒ v<sub>max</sub><sup>2</sup> = 4 ⇒ <b>v<sub>max</sub> = 2 m s<sup>-1</sup></b>.<br><br><b>(iii) Speed at x = 0.1 m:</b><br>U(0.1) = 1/2 k x<sup>2</sup> = 1/2 (50) (0.01) = 0.25 J.<br>E<sub>k</sub>(0.1) = E - U = 1.0 - 0.25 = 0.75 J.<br>1/2 (0.5) v<sup>2</sup> = 0.75 ⇒ 0.25 v<sup>2</sup> = 0.75 ⇒ v<sup>2</sup> = 3 ⇒ <b>v = √3 ≈ 1.732 m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q94: Vertical Circle Loop-the-Loop Rollercoaster Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A rollercoaster car of mass 500 kg enters a vertical circular loop of radius 20 m. Calculate (i) min entry speed at bottom, (ii) normal force from track at top if speed at top is 15 m s<sup>-1</sup> (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Radius r = 20 m, m = 500 kg, g = 10 m s<sup>-2</sup>.<br><br><b>(i) Min Entry Speed v<sub>L</sub> at bottom:</b><br>v<sub>L, min</sub> = √(5 g r) = √(5 × 10 × 20) = √1000 = <b>31.62 m s<sup>-1</sup></b>.<br><br><b>(ii) Normal Force N<sub>H</sub> at top when v<sub>H</sub> = 15 m s<sup>-1</sup>:</b><br>N<sub>H</sub> + mg = m v<sub>H</sub><sup>2</sup> / r.<br>N<sub>H</sub> = m (v<sub>H</sub><sup>2</sup> / r - g) = 500 [ (225 / 20) - 10 ] = 500 [ 11.25 - 10 ] = 500 (1.25) = <b>625 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q95: Elastic Collision 2D Oblique Scattering Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A billiard ball A of mass m moving at 5 m s<sup>-1</sup> strikes an identical stationary ball B elastically. After collision, ball A moves at angle 30° to initial direction. Calculate speeds of A and B and scattering angle of B.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      For equal masses in 2D elastic collision with target at rest, the two balls scatter at right angles to each other (θ<sub>1</sub> + θ<sub>2</sub> = 90°)!<br>Since θ<sub>1</sub> = 30°, θ<sub>2</sub> = 90° - 30° = <b>60°</b>.<br><br><b>Speeds:</b><br>v<sub>1</sub> = u cos θ<sub>1</sub> = 5 cos 30° = 5 (√3/2) = <b>4.33 m s<sup>-1</sup></b>.<br>v<sub>2</sub> = u sin θ<sub>1</sub> = 5 sin 30° = 5 (0.5) = <b>2.50 m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q96: Power and Efficiency of Motor Pump System Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">An electric motor pump of efficiency 80% lifts 36,000 litres of water per hour from a well 20 m deep. Calculate electric power input to motor (g = 10 m s<sup>-2</sup>, 1 L water = 1 kg).</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Mass of water m = 36,000 kg. Time t = 1 hour = 3600 s.<br>Output Work W = m g h = 36,000 × 10 × 20 = 7,200,000 J.<br>Output Power P<sub>out</sub> = W / t = 7,200,000 / 3600 = <b>2000 Watts (2 kW)</b>.<br><br>Efficiency η = P<sub>out</sub> / P<sub>in</sub> = 0.80.<br>Electric Power Input P<sub>in</sub> = P<sub>out</sub> / 0.80 = 2000 / 0.80 = <b>2500 Watts (2.5 kW)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q97: Potential Energy Function Graph & Force Stability Analysis</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Given potential energy U(x) = x<sup>3</sup>/3 - 4 x J. (i) Find equilibrium points. (ii) Determine stability of each equilibrium point.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Force F(x) = - dU/dx = - d/dx (x<sup>3</sup>/3 - 4 x) = -(x<sup>2</sup> - 4) = 4 - x<sup>2</sup>.<br><br><b>(i) Equilibrium Points (F = 0):</b><br>4 - x<sup>2</sup> = 0 ⇒ x<sup>2</sup> = 4 ⇒ <b>x = +2 m and x = -2 m</b>.<br><br><b>(ii) Stability Analysis (d<sup>2</sup>U/dx<sup>2</sup>):</b><br>d<sup>2</sup>U/dx<sup>2</sup> = d/dx (x<sup>2</sup> - 4) = 2 x.<br>- At x = +2 m: d<sup>2</sup>U/dx<sup>2</sup> = +4 > 0 ⇒ <b>Stable Equilibrium</b>.<br>- At x = -2 m: d<sup>2</sup>U/dx<sup>2</sup> = -4 < 0 ⇒ <b>Unstable Equilibrium</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q98: Ball Dropped and Bouncing Repeatedly Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A ball is dropped from height H<sub>0</sub> = 10 m on a floor with coefficient of restitution e = 0.8. Calculate (i) height H<sub>1</sub> after 1st rebound, (ii) total distance covered before coming to rest.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      (i) <b>Height after 1st rebound H<sub>1</sub>:</b><br>H<sub>1</sub> = e<sup>2</sup> H<sub>0</sub> = (0.8)<sup>2</sup> × 10 = 0.64 × 10 = <b>6.4 metres</b>.<br><br>(ii) <b>Total Distance Covered S:</b><br>S = H<sub>0</sub> + 2 H<sub>1</sub> + 2 H<sub>2</sub> + ... = H<sub>0</sub> + 2 e<sup>2</sup> H<sub>0</sub> + 2 e<sup>4</sup> H<sub>0</sub> + ...<br>S = H<sub>0</sub> [ 1 + 2 e<sup>2</sup> / (1 - e<sup>2</sup>) ] = H<sub>0</sub> [ (1 + e<sup>2</sup>) / (1 - e<sup>2</sup>) ].<br>S = 10 × [ (1 + 0.64) / (1 - 0.64) ] = 10 × (1.64 / 0.36) = 10 × 4.555 = <b>45.55 metres</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q99: Energy Conservation in Pendulum with String Cut at Apex</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A pendulum bob of mass 0.2 kg tied to string of 1 m is rotated in vertical circle. If string snaps at apex when speed is 4 m s<sup>-1</sup>, find horizontal distance where bob hits ground (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      When string snaps at apex (height h = 2 r = 2 m above bottom), bob becomes a horizontal projectile launched with velocity u<sub>x</sub> = 4 m/s at height 2 m.<br>Time to fall to ground: t = √(2 h / g) = √(2 × 2 / 10) = √(0.4) ≈ 0.632 s.<br>Horizontal distance x = u<sub>x</sub> × t = 4 × 0.632 = <b>2.53 metres</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #00c6ff; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q100: Master Inelastic Collision & Friction Stopping Distance Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 1 kg block moving at 10 m s<sup>-1</sup> on a rough table (μ<sub>k</sub> = 0.2) collides perfectly inelastically with a stationary 3 kg block. Calculate (i) common velocity, (ii) K.E. lost in collision, (iii) distance combined block travels before stopping.</div>\n    <div style=\"background: rgba(0, 198, 255, 0.05); border-left: 3.5px solid #00c6ff; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #00c6ff; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      m<sub>1</sub> = 1 kg, u<sub>1</sub> = 10 m/s, m<sub>2</sub> = 3 kg, u<sub>2</sub> = 0.<br><br><b>(i) Common Velocity V:</b><br>V = (1 × 10) / (1 + 3) = 10 / 4 = <b>2.5 m s<sup>-1</sup></b>.<br><br><b>(ii) K.E. Lost in Collision ΔE<sub>k</sub>:</b><br>Initial K.E. = 1/2 (1) (100) = 50 J.<br>Final K.E. = 1/2 (4) (2.5<sup>2</sup>) = 2 × 6.25 = 12.5 J.<br>Loss ΔE<sub>k</sub> = 50 - 12.5 = <b>37.5 Joules</b>.<br><br><b>(iii) Distance traveled before stopping:</b><br>Friction force on combined block (4 kg): f<sub>k</sub> = μ<sub>k</sub> M g = 0.2 × 4 × 10 = 8 N.<br>By Work-Energy Theorem: f<sub>k</sub> × s = Final K.E. ⇒ 8 × s = 12.5.<br><b>Stopping Distance s = 12.5 / 8 = 1.5625 metres</b>.\n    </div>\n  </div></div>";



